class SharedParamModule(nn.Module):
    def __init__(self):
        super().__init__()
        w = nn.Parameter(torch.randn(3, 3))
        self.w1 = w
        self.w2 = w

    def forward(self, x):
        return x @ self.w1 + x @ self.w2

